import json

# Try: 6,9,8 repeating every 3 diagonals, with special case for c-r=-9 (value 5)
# c-r = 4 → 6 (4 mod 3 = 1) ✓
# c-r = 5 → 9 (5 mod 3 = 2) ✓
# c-r = 6 → 8 (6 mod 3 = 0) ✓
# c-r = -9 → 5 (special)

rows = 16
cols = 16
output = [[0]*cols for _ in range(rows)]

for r in range(rows):
    for c in range(cols):
        diag = c - r
        if diag == -9:
            output[r][c] = 5
        else:
            mod = diag % 3
            if mod == 0:
                output[r][c] = 8
            elif mod == 1:
                output[r][c] = 6
            else:
                output[r][c] = 9

print("Pattern output:")
for i, row in enumerate(output):
    print(f"Row {i}: {' '.join(str(x) for x in row)}")
print("\nJSON:", json.dumps(output))
